// ==UserScript==
// @match http://127.0.0.1/*
// @run-at document-idle
// @noframes
// ==/UserScript==

async function main() {
  if (location.search.includes("page-error=1")) throw new Error("PAGE_LIFECYCLE_ACTUAL_ERROR");
  let node = document.getElementById("page-lifecycle-A");
  if (!node) { node = document.createElement("div"); node.id = "page-lifecycle-A"; document.body.prepend(node); }
  const count = Number(node.dataset.count || 0) + 1;
  node.dataset.count = String(count); node.textContent = "A r1 · " + count;
  return {version: 1, count, url: location.href};
}

